const STY = (bg) => `position:absolute;left:70px;width:800px;height:180px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;border-radius:46px;box-shadow:0 26px 40px -14px rgba(0,0,0,.5),inset 0 4px 0 rgba(255,255,255,.5);background:${bg};color:#ffffff;font-weight:800;line-height:1.1;font-size:46px;opacity:0;`;
const B1 = `linear-gradient(180deg,color-mix(in srgb,var(--acc) 72%,#fff),var(--acc) 55%,color-mix(in srgb,var(--acc) 84%,#000))`;
const B2 = `linear-gradient(180deg,color-mix(in srgb,var(--acc2) 72%,#fff),var(--acc2) 55%,color-mix(in srgb,var(--acc2) 84%,#000))`;

root.innerHTML = `
  <div id="c0" style="${STY(B1)}top:80px;">BLOCK SECRET<br>MODEL SWAPS</div>
  <div id="c1" style="${STY(B2)}top:430px;">FLASHPROVE<br>IDENTITY CHECK</div>
  <div id="c2" style="${STY(B1)}top:780px;">PRIVATE WEIGHTS<br>& DATA SECURED</div>
  <svg style="position:absolute;width:940px;height:1060px;fill:none;stroke:#ffffff;stroke-width:12;stroke-linecap:round;opacity:0.3">
    <path id="l0" d="M470 260 L470 430" />
    <path id="l1" d="M470 610 L470 780" />
    <circle id="v0" cx="470" cy="520" r="80" stroke="var(--acc2)" stroke-width="4" opacity="0" />
  </svg>
`;

const items = [0, 1, 2].map(i => root.querySelector('#c' + i));
const lines = [0, 1].map(i => {
  const el = root.querySelector('#l' + i);
  const len = el.getTotalLength();
  el.style.strokeDasharray = len;
  el.style.strokeDashoffset = len;
  return { el, len };
});
const check = root.querySelector('#v0');

function frame(t, p, d) {
  const tf = Math.min(t, d * 0.55);

  // Cards Entrance
  items.forEach((el, i) => {
    const s = spr(tf, i * 1.1, 0.82, 8);
    el.style.opacity = clamp(s * 1.5);
    const y = lerp(40, 0, E_OUT(clamp(s)));
    const sc = lerp(0.85, 1, E_OUT(clamp(s)));
    el.style.transform = `translateY(${y}px) scale(${sc})`;
  });

  // Lines Drawing
  lines.forEach((line, i) => {
    const s = spr(tf, 0.6 + i * 1.1, 0.9, 7);
    line.el.style.strokeDashoffset = line.len * (1 - s);
    line.el.style.opacity = 0.2 + s * 0.3;
  });

  // Middle Identity Accent
  const sCheck = spr(tf, 1.4, 0.7, 6);
  check.style.opacity = sCheck * 0.2;
  check.setAttribute('r', lerp(60, 120, E_OUT(sCheck)));
  check.style.strokeWidth = lerp(20, 2, E_OUT(sCheck));
}
